#!ibl edition=2
[def:외부PC준비]($PC,$환경조회=true) {
  [if:len($PC)==0] { return {ok:false,status:"invalid_input",reason:"PC 이름 또는 device_id가 필요합니다"} }
  $목록 = [self:limb]{op:"list"}
  $대상 = $목록.items >> [table:filter]{where:($행)=>$행.device_id==$PC}
  [if:len($대상)==0] {
    $대상 = $목록.items >> [table:filter]{where:($행)=>$행.alias==$PC and get($행,"revoked",false)==false and get($행,"expired",false)==false and (get($행,"registration",null)==null or get($행.registration,"state","active")!="removed")}
  }
  [if:len($대상)!=1] { return {ok:false,status:"target_not_unique",reason:"대상이 없거나 중복됩니다",items:$대상} }
  $손발 = $대상[0]
  $등록 = get($손발,"registration",{})
  [if:$등록==null] { $등록 = {} }
  $모드 = "portable"
  [if:len($등록)>0] { $모드 = "resident" }
  $기본 = {limb:$손발.device_id,limb_name:$손발.alias,helper_mode:$모드,registration:$등록,env:get($손발,"env",{})}
  [if:get($손발,"revoked",false) or get($손발,"expired",false) or get($등록,"state","active")!="active"] {
    return {**$기본,ok:false,status:"unavailable",reason:"폐기 또는 제거된 PC입니다"}
  }
  [if:get($등록,"paused",false)] { return {**$기본,ok:false,status:"paused",reason:"PC의 새 작업이 일시 중지돼 있습니다"} }
  [if:get($손발,"connected",false)==false] {
    return {**$기본,ok:false,status:"offline",reason:"PC 연결을 확인하세요. 상주 PC는 설정된 wake 경로로 깨울 수 있습니다"}
  }
  [if:$환경조회==false] { return {**$기본,ok:true,status:"connected"} }
  $정보 = [limbs:guestpc]{op:"info",limb:$손발.device_id}
  [if:len(get($정보.result,"error",""))>0] { return {**$기본,ok:false,status:"probe_failed",env:$정보.result} }
  return {**$기본,ok:true,status:"ready",env:$정보.result}
}

#!ibl edition=2
[def:외부PC작업확인]($작업,$대기=0) {
  $참조 = get($작업,"task_ref",{})
  [if:get($참조,"kind","")!="guestpc" or len(get($참조,"task_id",""))==0 or len(get($작업,"limb",""))==0 or $대기<0 or $대기>240] {
    return {ok:false,status:"invalid_input",task:$작업,reason:"guestpc 접수증과 0~240초 대기가 필요합니다",settled:false,command_ok:null}
  }
  $관측 = {}
  [try] { $관측 = [self:task]{op:"wait",ref:$참조,timeout:$대기} }
  [catch] {
    $관측 = get($error,"details",{})
    $관측 = get($관측,"task_observation",$관측)
    [if:get($관측,"task_ref",{})!=$참조 or len(get($관측,"state",""))==0] {
      return {**$작업,ok:false,status:"observation_failed",settled:false,command_ok:null,reason:$error.message}
    }
  }
  $상태 = $관측.state
  $결과 = get($관측,"result",null)
  [if:$결과==null] { $결과 = get($관측,"execution_result",null) }
  $진행 = get($관측,"progress",null)
  $실패 = get($관측,"failure",null)
  [if:$결과==null and $상태 in ["failed","cancelled","unknown","interrupted"] and get($작업,"helper_mode","")=="resident"] {
    [try] {
      $기록 = [limbs:guestpc]{op:"history",limb:$작업.limb,job:$참조.task_id}
      [if:len($기록.tasks)==1] { $결과 = $기록.tasks[0].result }
    } [catch] { $실패 = {task_failure:$실패,history_failure:$error.message} }
  }
  $종료 = null
  $성공 = null
  [if:$상태 in ["failed","cancelled","interrupted"]] { $성공 = false }
  [if:$결과!=null] {
    $종료 = get($결과,"exit",null)
    [if:$상태=="succeeded"] {
      [if:$종료!=null] { $성공 = $종료==0 and get($결과,"timeout",false)==false and len(get($결과,"error",""))==0 }
      [if:$종료==null and get($작업,"op","shell") in ["transfer","info","wake"]] { $성공 = len(get($결과,"error",""))==0 }
    }
  }
  return {**$작업,ok:true,status:$상태,limb_name:get($작업,"limb_name",$작업.limb),
    settled:$상태 in ["succeeded","failed","cancelled","interrupted"],command_ok:$성공,exit:$종료,
    started_at:get($관측,"started_at",null),ended_at:get($관측,"ended_at",null),seconds:get($관측,"seconds",null),
    history_args:get($관측,"history_args",null),progress_scope:get($관측,"progress_scope",null),
    outcome:get($관측,"outcome",$상태),
    timed_out:get($관측,"timed_out",false),progress:$진행,result:$결과,failure:$실패}
}

#!ibl edition=2
[def:외부PC작업실행]($PC,$명령,$작업폴더,$셸="",$실행제한=1800,$대기=0,$입력="",$환경초기화=false,$요청ID="",$환경={},$모드="background") {
  [if:len($PC)==0 or len($명령)==0 or len($작업폴더)==0 or $실행제한<1 or $실행제한>86400 or $대기<0 or $대기>240] {
    return {ok:false,status:"invalid_input",reason:"PC·명령·작업폴더, 1~86400초 실행제한, 0~240초 대기가 필요합니다"}
  }
  [if:$모드=="observe" and $실행제한>10] { return {ok:false,status:"invalid_input",reason:"확인용 observe 모드는 실행제한 1~10초가 필요합니다"} }
  $접수 = [limbs:guestpc]{op:"shell",limb:$PC,cmd:$명령,cwd:$작업폴더,shell:$셸,
    timeout:$실행제한,background:true,stdin:$입력,reset:$환경초기화,request_id:$요청ID,env:$환경,mode:$모드}
  $작업 = {**$접수,limb_name:get($접수,"limb_name",$PC),op:"shell"}
  $확인 = [fn:외부PC작업확인]{작업:$작업,대기:$대기}
  return {**$작업,ok:true,status:"accepted",cwd:$작업폴더,observation:$확인}
}

#!ibl edition=2
[def:외부PC작업마무리]($PC,$작업들,$산출물=[],$해제=false) {
  [if:len($PC)==0 or len($작업들)==0] {
    return {ok:false,status:"invalid_input",detached:false,reason:"PC와 확인할 작업 목록이 필요합니다"}
  }
  $첫작업 = $작업들[0]
  $다른대상 = $작업들 >> [table:filter]{where:($행)=>get($행,"limb","")!=get($첫작업,"limb","")}
  [if:len(get($첫작업,"limb",""))==0 or len($다른대상)>0 or ($PC!=$첫작업.limb and $PC!=get($첫작업,"limb_name",""))] {
    return {ok:false,status:"target_mismatch",detached:false,reason:"모든 작업과 마무리 대상 PC가 같아야 합니다"}
  }
  $확인들 = $작업들 >> [table:each] { [fn:외부PC작업확인]{작업:$it,대기:0} }
  $미확정 = $확인들 >> [table:filter]{where:($행)=>$행.settled==false}
  $미성공 = $확인들 >> [table:filter]{where:($행)=>$행.command_ok!=true}
  $기본 = {limb:$첫작업.limb,commands_ok:len($미성공)==0,items:$확인들,artifacts:$산출물,artifacts_verified:false,detached:false}
  [if:len($미확정)>0] { return {**$기본,ok:false,status:"unfinished"} }
  [if:$해제==false] { return {**$기본,ok:len($미성공)==0,status:"settled"} }
  $목록 = [self:limb]{op:"list"}
  $대상 = $목록.items >> [table:filter]{where:($행)=>$행.device_id==$첫작업.limb}
  [if:len($대상)!=1] { return {**$기본,ok:false,status:"target_not_unique"} }
  [if:get($대상[0],"registration",null)!=null] {
    return {**$기본,ok:false,status:"detach_not_supported",reason:"상주 PC는 유지합니다. 제거가 목적일 때만 self:limb remove를 별도로 호출하세요"}
  }
  $해제결과 = null
  $종료확인 = false
  [try] {
    $해제결과 = [limbs:guestpc]{op:"detach",limb:$첫작업.limb}
    $종료확인 = get($해제결과,"helper_exited",false)
  } [catch] { $해제결과 = {reason:$error.message} }
  return {**$기본,ok:len($미성공)==0 and $종료확인,status:"settled",detached:$종료확인,detach_result:$해제결과}
}

#!ibl edition=2
[def:외부PC파일보내기]($PC,$중앙경로,$원격경로,$요청ID,$대기=0,$작업={},$전송ID="") {
  [if:len($PC)==0 or len($중앙경로)==0 or len($원격경로)==0 or len($요청ID)==0 or $대기<0 or $대기>240] { return {ok:false,status:"invalid_input",reason:"PC·중앙경로·원격경로·요청ID와 0~240초 대기가 필요합니다"} }
  $접수 = $작업
  [if:len($작업)==0] {
    $준비 = [fn:외부PC준비]{PC:$PC,환경조회:false}
    [if:$준비.ok==false] { return $준비 }
    [if:$준비.helper_mode!="resident"] { return {ok:false,status:"resident_required"} }
    $접수 = [limbs:guestpc]{op:"transfer",action:"send",limb:$준비.limb,local_path:$중앙경로,path:$원격경로,request_id:$요청ID,transfer_id:$전송ID}
    $접수 = {**$접수,pc_request:$PC,local_path:$중앙경로,remote_path:$원격경로,transfer_action:"send"}
  }
  [if:get($접수,"pc_request","")!=$PC or get($접수,"local_path","")!=$중앙경로 or get($접수,"remote_path","")!=$원격경로 or get($접수,"request_id","")!=$요청ID or get($접수,"transfer_action","")!="send"] { return {ok:false,status:"resume_mismatch",task:$작업} }
  [if:len($전송ID)>0 and get($접수,"transfer_id","")!=$전송ID] { return {ok:false,status:"resume_mismatch",task:$작업} }
  $확인 = [fn:외부PC작업확인]{작업:$접수,대기:$대기}
  [if:$확인.ok==false] { return $확인 }
  [if:$확인.command_ok==true and get($확인.result,"state","")=="committed" and len(get($확인.result,"sha256",""))==64 and get($확인.result,"path","")==$원격경로] { return {**$확인,ok:true,status:"delivered",path:$원격경로,sha256:get($확인.result,"sha256",null),verified:true} }
  return {**$확인,ok:false,verified:false}
}

#!ibl edition=2
[def:외부PC파일가져오기]($PC,$중앙경로,$원격경로,$요청ID,$대기=0,$작업={},$전송ID="") {
  [if:len($PC)==0 or len($중앙경로)==0 or len($원격경로)==0 or len($요청ID)==0 or $대기<0 or $대기>240] { return {ok:false,status:"invalid_input",reason:"PC·중앙경로·원격경로·요청ID와 0~240초 대기가 필요합니다"} }
  $접수 = $작업
  [if:len($작업)==0] {
    $준비 = [fn:외부PC준비]{PC:$PC,환경조회:false}
    [if:$준비.ok==false] { return $준비 }
    [if:$준비.helper_mode!="resident"] { return {ok:false,status:"resident_required"} }
    $접수 = [limbs:guestpc]{op:"transfer",action:"receive",limb:$준비.limb,local_path:$중앙경로,path:$원격경로,request_id:$요청ID,transfer_id:$전송ID}
    $접수 = {**$접수,pc_request:$PC,local_path:$중앙경로,remote_path:$원격경로,transfer_action:"receive"}
  }
  [if:get($접수,"pc_request","")!=$PC or get($접수,"local_path","")!=$중앙경로 or get($접수,"remote_path","")!=$원격경로 or get($접수,"request_id","")!=$요청ID or get($접수,"transfer_action","")!="receive"] { return {ok:false,status:"resume_mismatch",task:$작업} }
  [if:len($전송ID)>0 and get($접수,"transfer_id","")!=$전송ID] { return {ok:false,status:"resume_mismatch",task:$작업} }
  $확인 = [fn:외부PC작업확인]{작업:$접수,대기:$대기}
  [if:$확인.ok==false] { return $확인 }
  [if:$확인.command_ok!=true] { return {**$확인,ok:false,collected:false} }
  [try] {
    $파일 = [limbs:guestpc]{op:"transfer",action:"collect",limb:$접수.limb,transfer_id:$접수.transfer_id,local_path:$중앙경로}
    return {**$확인,ok:true,status:"collected",collected:true,path:$파일.path,sha256:$파일.sha256,verified:true}
  } [catch] { return {**$확인,ok:false,status:"collect_failed",collected:false,reason:$error.message} }
}

#!ibl edition=2
[def:외부PC깨워준비]($PC,$요청ID,$대기=30,$작업={}) {
  [if:len($PC)==0 or len($요청ID)==0 or $대기<0 or $대기>240] { return {ok:false,status:"invalid_input",reason:"PC·요청ID와 0~240초 대기가 필요합니다"} }
  $접수 = $작업
  [if:len($작업)==0] {
    $준비 = [fn:외부PC준비]{PC:$PC,환경조회:false}
    [if:$준비.ok==false and $준비.status!="offline"] { return $준비 }
    [if:get($준비,"helper_mode","")!="resident"] { return {ok:false,status:"resident_required"} }
    $깨우기 = null
    [if:$준비.status=="offline"] { $깨우기 = [limbs:guestpc]{op:"wake",limb:get($준비,"limb","")} }
    $접수 = [limbs:guestpc]{op:"info",limb:get($준비,"limb",""),background:true,request_id:$요청ID}
    $접수 = {**$접수,pc_request:$PC,wake_receipt:$깨우기}
  }
  [if:get($접수,"pc_request","")!=$PC or get($접수,"request_id","")!=$요청ID or get($접수,"op","")!="info"] { return {ok:false,status:"resume_mismatch",task:$작업} }
  $확인 = [fn:외부PC작업확인]{작업:$접수,대기:$대기}
  $준비됨 = false
  [if:get($확인,"command_ok",false)==true] { $준비됨 = len(get($확인.result,"os",""))>0 }
  return {**$확인,ok:$준비됨,ready:$준비됨,env:get($확인,"result",null)}
}

#!ibl edition=2
[def:외부PC작업중지확인]($작업,$대기=0) {
  [if:$대기<0 or $대기>240] { return {ok:false,status:"invalid_input",stopped:false} }
  $확인 = [fn:외부PC작업확인]{작업:$작업,대기:0}
  [if:$확인.ok==false or $확인.settled or $확인.status=="unknown"] { return {**$확인,stopped:$확인.status=="cancelled"} }
  [try] { $취소 = [self:task]{op:"cancel",ref:$작업.task_ref} }
  [catch] { return {**$확인,ok:false,stopped:false,cancel_error:$error.message} }
  $확인 = [fn:외부PC작업확인]{작업:$작업,대기:$대기}
  return {**$확인,stopped:$확인.status=="cancelled",cancel_observation:$취소}
}

#!ibl edition=2
[def:외부PC재생]($PC,$소스,$요청ID,$모드="background",$실행제한=86400,$작업={}) {
  [if:len($PC)==0 or len($소스)==0 or len($요청ID)==0 or not ($모드 in ["background","interactive"]) or $실행제한<1 or $실행제한>86400] { return {ok:false,status:"invalid_input"} }
  $접수 = $작업
  [if:len($작업)==0] {
    $준비 = [fn:외부PC준비]{PC:$PC,환경조회:false}
    [if:$준비.ok==false] { return $준비 }
    [if:$준비.helper_mode!="resident"] { return {ok:false,status:"resident_required"} }
    $인자 = {op:"media",limb:$준비.limb,mode:$모드,timeout:$실행제한,request_id:$요청ID}
    [if:$소스[:8]=="https://" or $소스[:7]=="http://"] { $인자 = {**$인자,url:$소스} }
    [else] { $인자 = {**$인자,path:$소스} }
    $접수 = [limbs:guestpc]{**$인자}
    $접수 = {**$접수,pc_request:$PC,media_source:$소스,media_mode:$모드,media_timeout:$실행제한}
  }
  [if:get($접수,"pc_request","")!=$PC or get($접수,"media_source","")!=$소스 or get($접수,"request_id","")!=$요청ID or get($접수,"media_mode","")!=$모드 or get($접수,"media_timeout",0)!=$실행제한] { return {ok:false,status:"resume_mismatch",task:$작업} }
  $확인 = [fn:외부PC작업확인]{작업:$접수,대기:0}
  return {**$확인,playback_verified:false,reason:"접수·작업 상태만 확인합니다. running은 실제 소리가 들린다는 증명이 아닙니다"}
}
